trait Cost { fn cost(&self) -> u64; }
struct Item(u64);
impl Cost for Item { fn cost(&self)->u64 { self.0 } }
struct Pair(u64,u64);
impl Cost for Pair { fn cost(&self)->u64 { self.0+self.1 } }
fn total<T: Cost>(xs: &[T]) -> u64 {
    xs.iter().map(|x| x.cost()).sum()
}
fn main() {}

