trait Op { fn apply(&self, x:i32)->i32; }
struct Add(i32); impl Op for Add { fn apply(&self,x:i32)->i32 { x+self.0 } }
struct Mul(i32); impl Op for Mul { fn apply(&self,x:i32)->i32 { x*self.0 } }
fn pipeline(ops: &[&dyn Op], x:i32)->i32 {
    ops.iter().fold(x, |value, op| op.apply(value))
}
fn main() {}

check.tests:
#[cfg(test)]
mod lesson_tests {
    use super::*;
    #[test]
    fn contract() {
let add=Add(2); let mul=Mul(3);
assert_eq!(pipeline(&[&add,&mul],4),18); assert_eq!(pipeline(&[&mul,&add],4),14); assert_eq!(pipeline(&[],7),7);
    }
}
